import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.BGkQCay2.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),n={name:"guide/faq.md"};function i(l,e,s,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-vex" tabindex="-1">What is Vex? <a class="header-anchor" href="#what-is-vex" aria-label="Permalink to &quot;What is Vex?&quot;">​</a></h3><p>Vex is a pre-1.0 systems programming language with explicit ownership, borrowing, native compilation, and language-level concurrency features. SIMD, GPU, FFI, and standard-library surfaces are documented with their current maturity rather than treated as uniformly complete.</p><h3 id="is-vex-ready-for-production" tabindex="-1">Is Vex ready for production? <a class="header-anchor" href="#is-vex-ready-for-production" aria-label="Permalink to &quot;Is Vex ready for production?&quot;">​</a></h3><p>Not as a general guarantee. The compiler, runtime, and standard library are still evolving. Use Vex for experiments, tools, and projects where you can pin the compiler and validate the exact target yourself. The <a href="/docs/guide/language-status">language status</a> page records known boundaries.</p><h3 id="what-platforms-does-vex-support" tabindex="-1">What platforms does Vex support? <a class="header-anchor" href="#what-platforms-does-vex-support" aria-label="Permalink to &quot;What platforms does Vex support?&quot;">​</a></h3><p>macOS ARM64 is the primary development platform for this checkout. Other targets are experimental until their compiler, runtime, linker, and native-library paths have been validated together. See <a href="/docs/guide/platform-support">Platform Support</a>.</p><h3 id="what-license-is-vex-under" tabindex="-1">What license is Vex under? <a class="header-anchor" href="#what-license-is-vex-under" aria-label="Permalink to &quot;What license is Vex under?&quot;">​</a></h3><p>The repository is distributed under the MIT license. Check the repository license file for the authoritative text.</p><h2 id="language-design" tabindex="-1">Language design <a class="header-anchor" href="#language-design" aria-label="Permalink to &quot;Language design&quot;">​</a></h2><h3 id="why-does-vex-use-let" tabindex="-1">Why does Vex use <code>let!</code>? <a class="header-anchor" href="#why-does-vex-use-let" aria-label="Permalink to &quot;Why does Vex use `let!`?&quot;">​</a></h3><p><code>let</code> creates an immutable binding. <code>let!</code> makes local mutation explicit. Mutable references use the corresponding <code>!</code> form. This convention makes mutation visible in code and diagnostics.</p><h3 id="does-vex-have-a-garbage-collector" tabindex="-1">Does Vex have a garbage collector? <a class="header-anchor" href="#does-vex-have-a-garbage-collector" aria-label="Permalink to &quot;Does Vex have a garbage collector?&quot;">​</a></h3><p>Vex&#39;s core model is ownership and borrowing rather than a tracing garbage collector. Heap abstractions and runtime-managed values are still subject to the implementation status of the selected library and target.</p><h3 id="how-are-errors-represented" tabindex="-1">How are errors represented? <a class="header-anchor" href="#how-are-errors-represented" aria-label="Permalink to &quot;How are errors represented?&quot;">​</a></h3><p>Use enum-shaped <code>Option&lt;T&gt;</code> and <code>Result&lt;T, E&gt;</code> values, pattern matching, and the supported propagation operators. See <a href="/docs/guide/types/enums">Enums</a> and <a href="/docs/guide/error-handling">Error Handling</a>.</p><h2 id="compilation" tabindex="-1">Compilation <a class="header-anchor" href="#compilation" aria-label="Permalink to &quot;Compilation&quot;">​</a></h2><h3 id="what-is-the-difference-between-vex-lint-vex-run-and-vex-compile" tabindex="-1">What is the difference between <code>vex lint</code>, <code>vex run</code>, and <code>vex compile</code>? <a class="header-anchor" href="#what-is-the-difference-between-vex-lint-vex-run-and-vex-compile" aria-label="Permalink to &quot;What is the difference between `vex lint`, `vex run`, and `vex compile`?&quot;">​</a></h3><p><code>vex lint</code> performs correctness analysis and configured semantic lints without requiring a final executable. <code>vex run</code> builds a temporary executable and launches it. <code>vex compile</code> produces a persistent artifact. Runtime compilation and linking can fail even when source analysis succeeds.</p><h3 id="can-i-cross-compile" tabindex="-1">Can I cross-compile? <a class="header-anchor" href="#can-i-cross-compile" aria-label="Permalink to &quot;Can I cross-compile?&quot;">​</a></h3><p>The compiler exposes target-related options, but cross-compilation is not automatically a supported runtime configuration. Validate the target&#39;s runtime, linker, native dependencies, and standard library before relying on it.</p><h3 id="why-should-i-use-vex-lint-during-development" tabindex="-1">Why should I use <code>vex lint</code> during development? <a class="header-anchor" href="#why-should-i-use-vex-lint-during-development" aria-label="Permalink to &quot;Why should I use `vex lint` during development?&quot;">​</a></h3><p>It gives fast feedback about syntax, types, ownership, and borrowing without requiring the full runtime and native-linking path. Use <code>vex run</code> only after checking the target-specific execution path.</p><h2 id="memory-and-safety" tabindex="-1">Memory and safety <a class="header-anchor" href="#memory-and-safety" aria-label="Permalink to &quot;Memory and safety&quot;">​</a></h2><h3 id="what-are-box-t-ptr-t-and-raw-pointers" tabindex="-1">What are <code>Box&lt;T&gt;</code>, <code>Ptr&lt;T&gt;</code>, and raw pointers? <a class="header-anchor" href="#what-are-box-t-ptr-t-and-raw-pointers" aria-label="Permalink to &quot;What are `Box&lt;T&gt;`, `Ptr&lt;T&gt;`, and raw pointers?&quot;">​</a></h3><ul><li><code>Box&lt;T&gt;</code> is an owning heap abstraction.</li><li><code>Ptr&lt;T&gt;</code> is a typed pointer abstraction for lower-level operations.</li><li>Raw pointers are unsafe boundary tools for FFI and specialized systems code.</li></ul><p>Ownership and borrowing still apply around all three. Keep raw operations inside small, tested boundaries.</p><h3 id="what-should-i-do-when-the-borrow-checker-rejects-code" tabindex="-1">What should I do when the borrow checker rejects code? <a class="header-anchor" href="#what-should-i-do-when-the-borrow-checker-rejects-code" aria-label="Permalink to &quot;What should I do when the borrow checker rejects code?&quot;">​</a></h3><p>Reduce the lifetime of the borrow, make the ownership transfer explicit, or restructure the operation so mutable and immutable access do not overlap. Do not bypass the checker until the boundary and safety invariant are documented.</p><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><h3 id="are-go-channels-async-and-await-stable" tabindex="-1">Are <code>go</code>, channels, <code>async</code>, and <code>await</code> stable? <a class="header-anchor" href="#are-go-channels-async-and-await-stable" aria-label="Permalink to &quot;Are `go`, channels, `async`, and `await` stable?&quot;">​</a></h3><p>They are implemented language surfaces, but runtime behavior is experimental and platform-dependent. Channels and detached work also require an explicit shutdown and ownership design. See <a href="/docs/guide/concurrency/overview">Concurrency Overview</a> and <a href="/docs/guide/concurrency/channels">Channels</a>.</p><h3 id="can-a-channel-deadlock" tabindex="-1">Can a channel deadlock? <a class="header-anchor" href="#can-a-channel-deadlock" aria-label="Permalink to &quot;Can a channel deadlock?&quot;">​</a></h3><p>Yes. Capacity, send/receive ordering, task shutdown, and ownership transfers all matter. Start with a small checked example and test the runtime behavior on the target platform.</p><h2 id="tooling-and-libraries" tabindex="-1">Tooling and libraries <a class="header-anchor" href="#tooling-and-libraries" aria-label="Permalink to &quot;Tooling and libraries&quot;">​</a></h2><h3 id="does-vex-have-a-package-manager" tabindex="-1">Does Vex have a package manager? <a class="header-anchor" href="#does-vex-have-a-package-manager" aria-label="Permalink to &quot;Does Vex have a package manager?&quot;">​</a></h3><p>The repository contains package-management commands and documentation, but the package surface is still partial. Verify the exact command and manifest fields with <code>vex &lt;command&gt; --help</code> and the <a href="/docs/references/vex-pm-reference">package manager reference</a>.</p><h3 id="can-i-call-c-libraries-from-vex" tabindex="-1">Can I call C libraries from Vex? <a class="header-anchor" href="#can-i-call-c-libraries-from-vex" aria-label="Permalink to &quot;Can I call C libraries from Vex?&quot;">​</a></h3><p>FFI syntax exists, but ABI, linking, ownership, and platform support must be checked for the selected provider and target. Start with the <a href="/docs/guide/ffi">FFI guide</a>.</p><h3 id="where-should-i-report-an-internal-compiler-error" tabindex="-1">Where should I report an internal compiler error? <a class="header-anchor" href="#where-should-i-report-an-internal-compiler-error" aria-label="Permalink to &quot;Where should I report an internal compiler error?&quot;">​</a></h3><p>Record the source, compiler version, repository revision, platform, command, and full diagnostic in the repository issue tracker. If the problem is already reproduced locally, link the relevant compiler issue report from the documentation.</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><ul><li>Read the <a href="/docs/guide/installation">installation guide</a> and <a href="/docs/guide/language-status">language status</a>.</li><li>Use <code>vex --help</code> and <code>vex &lt;command&gt; --help</code> for the binary you actually built.</li><li>Include the exact compiler version and platform in bug reports.</li></ul>',44)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
